// See zonos3-short-text.h.
#include "zonos3-short-text.h"

#include "json.hpp"
#include "zonos3-short-text-json.h"  // generated by CMake: zonos3_short_text_json[], zonos3_short_text_json_len

#include <stdexcept>

namespace zonos3_short {

namespace {

std::vector<uint8_t> b64_decode(const std::string & in) {
    static const std::string A = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    std::vector<uint8_t> out;
    uint32_t val = 0;
    int bits = 0;
    for (char c : in) {
        if (c == '=') break;
        const size_t d = A.find(c);
        if (d == std::string::npos) throw std::runtime_error("short_text.json: invalid base64 in silence.weights");
        val = (val << 6) | (uint32_t) d;
        bits += 6;
        if (bits >= 8) {
            bits -= 8;
            out.push_back((uint8_t) ((val >> bits) & 0xFF));
        }
    }
    return out;
}

}  // namespace

const Registry & registry() {
    static const Registry r = [] {
        const auto d = nlohmann::json::parse(std::string((const char *) zonos3_short_text_json, zonos3_short_text_json_len));
        const auto & s = d.at("silence");
        const auto & cut = d.at("cut");
        Registry out;
        out.pause_marker = d.at("pause_marker").get<std::string>();
        out.max_words = d.at("max_words").get<int>();
        out.max_ratio[0] = d.at("max_ratio").at(0).get<int>();
        out.max_ratio[1] = d.at("max_ratio").at(1).get<int>();
        out.lookback = cut.at("lookback").get<int>();
        out.min_voiced = cut.at("min_voiced").get<int>();
        out.max_frames = cut.at("max_frames").get<int>();
        out.max_retries = cut.at("max_retries").get<int>();
        out.n_codebooks = s.at("n_codebooks").get<int>();
        out.codebook_size = s.at("codebook_size").get<int>();
        out.threshold = s.at("threshold").get<int>();
        const auto bytes = b64_decode(s.at("weights").get<std::string>());
        if (bytes.size() != (size_t) out.n_codebooks * out.codebook_size)
            throw std::runtime_error("short_text.json: silence.weights is not n_codebooks x codebook_size int8");
        out.weights.assign(bytes.size(), 0);
        for (size_t i = 0; i < bytes.size(); ++i) out.weights[i] = (int8_t) bytes[i];
        for (const auto & [lang, filler] : d.at("fillers").items()) out.fillers[lang] = filler.get<std::string>();
        return out;
    }();
    return r;
}

ShortCut::ShortCut(int filler_token, int n_codebooks)
    : reg_(registry()), filler_token_(filler_token), n_codebooks_(n_codebooks) {}

void ShortCut::truncate(int n) {
    if ((int) rows_.size() > n) rows_.resize(n);
    const int keep = std::max(0, n - n_codebooks_ + 1);
    if ((int) silent_.size() > keep) silent_.resize(keep);
    if (enter_ && *enter_ >= n) enter_.reset();
    decided_.reset();
    decide();
}

void ShortCut::observe_reading(int frame, int pos) {
    if (!enter_ && pos >= filler_token_) {
        enter_ = frame;
        decide();
    }
}

void ShortCut::observe_row(const std::vector<int32_t> & row) {
    rows_.emplace_back(row.begin(), row.begin() + std::min<size_t>(row.size(), (size_t) n_codebooks_));
    const int f = (int) rows_.size() - n_codebooks_;  // the frame this row completes
    if (f >= 0) {
        silent_.push_back(is_silent(f));
        decide();
    }
}

bool ShortCut::is_silent(int f) const {
    int64_t score = 0;
    for (int k = 0; k < n_codebooks_; ++k) {
        const auto & row = rows_[f + k];
        const int32_t c = k < (int) row.size() ? row[k] : -1;
        if (c < 0 || c >= reg_.codebook_size) return false;
        score += reg_.weights[(size_t) k * reg_.codebook_size + c];
    }
    return score > reg_.threshold;
}

void ShortCut::decide() {
    if (decided_ || !enter_) return;
    int voiced = 0;
    for (int f = 0; f < (int) silent_.size(); ++f) {
        voiced += !silent_[f];
        if (f < *enter_ - reg_.lookback) continue;
        if (f + 1 - *enter_ > reg_.max_frames) {
            decided_.emplace("run_on", *enter_);
            return;
        }
        if (silent_[f] && voiced >= reg_.min_voiced) {
            decided_.emplace("cut", f + 1);
            return;
        }
    }
}

}  // namespace zonos3_short
